  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/c7ff90544ca41795/shell/view-menu.tsx FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/c7ff90544ca41795/shell/viz.tsx FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
